export class AppComponent {
  constructor(http) {
    this.http = http;
    this.api = 'http://localhost:5000/api';
    this.token = localStorage.getItem('attendify_token') || '';
    this.user = JSON.parse(localStorage.getItem('attendify_user') || 'null');
    this.page = 'dashboard';
    this.busy = false;
    this.message = '';
    this.error = '';
    this.todayAttendance = null;
    this.attendance = [];
    this.leaves = [];
    this.balance = {};
    this.employees = [];
    this.adminAttendance = [];
    this.adminLeaves = [];
    this.summary = {
      total: 0,
      present: 0,
      absent: 0,
      late: 0,
      onLeave: 0
    };
    this.showEditEmployeeModal = false;
    this.selectedEmployee = null;
    this.savingEmployee = false;
    this.loginForm = {
      email: 'employee@attendify.local',
      password: 'Employee@12345'
    };
    this.profileForm = {
      phone: '',
      address: ''
    };
    this.passwordForm = {
      currentPassword: '',
      newPassword: '',
      confirmPassword: ''
    };
    this.notificationSettings = {
      attendanceReminder: true,
      leaveUpdates: true,
      announcements: true
    };
    this.leaveForm = {
      type: 'annual',
      startDate: '',
      endDate: '',
      reason: ''
    };
    this.employeeForm = {
      name: '',
      email: '',
      password: 'Welcome@123',
      employeeId: '',
      department: '',
      designation: '',
      phone: '',
      annual: 24,
      sick: 8,
      casual: 10
    };
    // EDIT EMPLOYEE PROFILE
    this.showEditEmployeeModal = false;
    this.selectedEmployee = null;
    this.savingEmployee = false;
    this.editEmployeeForm = {
      name: '',
      email: '',
      employeeId: '',
      phone: '',
      department: '',
      designation: '',
      joiningDate: '',
      address: '',
      annual: 24,
      sick: 8,
      casual: 10
    };
    this.selectedPhoto = null;
    this.selectedPreview = '';
    this.latitude = null;
    this.longitude = null;
    this.accuracy = null;
    this.currentDate = new Date();
    if (this.token && this.user) {
      this.loadData();
    }
  }
  // ADMIN CHECK
  get isAdmin() {
    return this.user?.role === 'admin';
  }
  // AUTHORIZATION HEADERS
  get headers() {
    return {
      headers: new HttpHeaders({
        Authorization: `Bearer ${this.token}`
      })
    };
  }
  // NOTIFICATION MESSAGE
  notify(text, isError = false) {
    this.message = isError ? '' : text;
    this.error = isError ? text : '';
    setTimeout(() => {
      this.message = '';
      this.error = '';
    }, 4500);
  }
  // LOGIN
  login() {
    this.busy = true;
    this.http.post(`${this.api}/auth/login`, this.loginForm).subscribe({
